import React, { useEffect, useState } from "react";

function App() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const token = localStorage.getItem("token"); // put your JWT here
        const res = await fetch("http://localhost:5000/api/orders/my", {
          headers: { Authorization: "Bearer " + token }
        });
        const data = await res.json();
        setOrders(data);
      } catch (err) {
        console.log(err);
      }
    };
    fetchOrders();
  }, []);

  return (
    <div>
      <h1>Order Tracking System</h1>
      <ul>
        {orders.map((order) => (
          <li key={order._id}>
            {order.productName} - {order.status} - {order.quantity}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
